import { unstable_cache } from 'next/cache';
import { getAllProducts } from './db';

/**
 * Cached wrapper around getAllProducts.
 *
 * Data is served from Next.js's Data Cache until revalidateTag('products') is
 * called, at which point the next request re-populates the cache from the
 * source.  All routes that call getCachedProducts share this single cache
 * entry, so one invalidation propagates across every catalog view.
 */
export const getCachedProducts = unstable_cache(
  getAllProducts,
  ['products'],
  { tags: ['products'] },
);

