import { revalidateTag } from 'next/cache';
import { getCachedProducts } from '@/lib/products';

// Render on every request so the cached data layer is always consulted.
// The page itself is never statically frozen; only the Data Cache entry
// (keyed by the 'products' tag) provides the caching benefit.
export const dynamic = 'force-dynamic';

export default async function AdminCatalogPage() {
  const products = await getCachedProducts();

  // Inline Server Action — submitted via a plain HTML form POST.
  // revalidateTag purges the 'products' Data Cache entry so the next request
  // to any view that calls getCachedProducts fetches fresh ERP/PIM data.
  // The action returns immediately; no request blocks on the upstream sync.
  async function syncCatalog() {
    'use server';
    revalidateTag('products');
  }

  return (
    <main style={{ fontFamily: 'system-ui, sans-serif', maxWidth: 900, margin: '0 auto', padding: '2rem' }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '1.5rem' }}>
        <div>
          <h1 style={{ margin: 0, fontSize: '1.5rem' }}>Product Catalog</h1>
          <p style={{ margin: '0.25rem 0 0', color: '#6b7280', fontSize: '0.875rem' }}>
            {products.length} products &mdash; data served from cache
          </p>
        </div>

        {/*
          Regular HTML form with a Server Action.
          Submitting invalidates the 'products' cache tag so all catalog
          views pick up the latest ERP/PIM data on their next render.
          The admin is not blocked waiting for the upstream sync to complete.
        */}
        <form action={syncCatalog}>
          <button
            type="submit"
            style={{
              padding: '0.5rem 1.125rem',
              background: '#2563eb',
              color: '#fff',
              border: 'none',
              borderRadius: '0.375rem',
              fontSize: '0.875rem',
              fontWeight: 600,
              cursor: 'pointer',
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </div>

      <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.875rem' }}>
        <thead>
          <tr style={{ background: '#f9fafb' }}>
            {(['SKU', 'Name', 'Price', 'Stock', 'Status'] as const).map(h => (
              <th
                key={h}
                style={{
                  padding: '0.625rem 0.75rem',
                  textAlign: h === 'Price' || h === 'Stock' ? 'right' : h === 'Status' ? 'center' : 'left',
                  borderBottom: '2px solid #e5e7eb',
                  color: '#374151',
                  fontWeight: 600,
                  letterSpacing: '0.02em',
                }}
              >
                {h}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {products.map((product, i) => (
            <tr key={product.id} style={{ background: i % 2 === 0 ? '#fff' : '#f9fafb' }}>
              <td style={{ padding: '0.625rem 0.75rem', borderBottom: '1px solid #e5e7eb', fontFamily: 'monospace', color: '#6b7280' }}>
                {product.sku}
              </td>
              <td style={{ padding: '0.625rem 0.75rem', borderBottom: '1px solid #e5e7eb' }}>
                {product.name}
              </td>
              <td style={{ padding: '0.625rem 0.75rem', textAlign: 'right', borderBottom: '1px solid #e5e7eb' }}>
                ${product.price.toLocaleString()}
              </td>
              <td style={{ padding: '0.625rem 0.75rem', textAlign: 'right', borderBottom: '1px solid #e5e7eb' }}>
                {product.stock}
              </td>
              <td style={{ padding: '0.625rem 0.75rem', textAlign: 'center', borderBottom: '1px solid #e5e7eb' }}>
                <span
                  style={{
                    display: 'inline-block',
                    padding: '0.2rem 0.6rem',
                    borderRadius: '9999px',
                    fontSize: '0.75rem',
                    fontWeight: 600,
                    background: product.available ? '#dcfce7' : '#fee2e2',
                    color: product.available ? '#15803d' : '#b91c1c',
                  }}
                >
                  {product.available ? 'Active' : 'Inactive'}
                </span>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  );
}

